class Solution {
public:
    int numDistinct(string s, string t) {
        int n = t.size();
        vector<unsigned long long> dp(n + 1, 0);
        dp[0] = 1;
        for (char c : s) {
            for (int j = n; j >= 1; --j) {
                if (c == t[j - 1]) {
                    dp[j] += dp[j - 1];
                }
            }
        }
        return dp[n];
    }
};

class Solution {
    public int numDistinct(String s, String t) {
        int n = t.length();
        double[] dp = new double[n + 1];
        dp[0] = 1;
        for (char c : s.toCharArray()) {
            for (int j = n; j >= 1; j--) {
                if (c == t.charAt(j - 1)) {
                    dp[j] += dp[j - 1];
                }
            }
        }
        return (int)dp[n];
    }
}

var numDistinct = function(s, t) {
    const n = t.length;
    const dp = new Array(n + 1).fill(0);
    dp[0] = 1;
    for (const c of s) {
        for (let j = n; j >= 1; j--) {
            if (c === t[j - 1]) {
                dp[j] += dp[j - 1];
            }
        }
    }
    return dp[n];
};
